			if( returnValueRef != null && (returnValueRef.getType() instanceof RefLikeType || dfa.includesPrimitiveInfoFlow()))
				dataFlowGraph.addEdge(r, InfoFlowAnalysis.getNodeForReturnRef(sm));
		}

		return dataFlowGraph;
	}

